def three_most_common(dancers):
    """
    Given a list of dancers, find the three most common elements and return them in descending order.

    Example:
    three_most_common(['Alice', 'Bob', 'Alice', 'John', 'Bob', 'Bob', 'John', 'Eve']) -> ['Bob', 'Alice', 'John']
    """

### Solution:


    dancer_count = {}
    for dancer in dancers:
        if dancer in dancer_count:
            dancer_count[dancer] += 1
        else:
            dancer_count[dancer] = 1
    sorted_dancers = sorted(dancer_count, key=lambda x: dancer_count[x], reverse=True)
    return sorted_dancers[:3]

### Problem:
def find_veterinarian(vet_schedule, pet_symptoms):

    """Given a veterinarian schedule and a pet's symptoms, find a veterinarian available to treat the pet based on the symptoms urgency."""

### Solution:


    # Sort the veterinarian schedule based on availability
    veterinarian_schedule = sorted(vet_schedule.items(), key=lambda x: x[1]['availability'])

    # Loop through the veterinarian schedule to find an available veterinarian
    for vet, details in veterinarian_schedule:

        # Check if the veterinarian is available
        if not details['availability']:
            continue

        # Check if the pet's symptoms match any of the veterinarian's expertise
        for symptom, urgency in pet_symptoms.items():

            # Short-circuiting: If symptom is not present in the veterinarian's expertise, move to next veterinarian
            if symptom not in details['expertise']:
                break

            # If symptom is present, check the urgency of the symptom
            if urgency >= details['expertise'][symptom]:
                return vet

    return "No available veterinarian found"


