    if (sortedString1 === sortedString2) {
      throw new Error("Error - The strings are anagrams of each other");
    }
  }

  checkRepeatedCharacters(string) {
    const charMap = {};
    for (let char of string) {
      if (charMap[char]) {
        throw new Error("Error - The returned string contains repeated characters");
      }
      charMap[char] = true;
    }
  }

  getLongerOrShorterString() {
    this.validateStrings();
    this.checkAnagrams();

    let longerString = this.string1;
    let shorterString = this.string2;

    if (this.string2.length > this.string1.length) {
      longerString = this.string2;
      shorterString = this.string1;
    }

    if (this.shouldReturnLonger) {
      this.checkRepeatedCharacters(longerString);
      return longerString;
    } else {
      this.checkRepeatedCharacters(shorterString);
      return shorterString;
    }
  }
}

// Example usage
