import com.sorting.arraysorter.ArraySorter;
import com.sorting.customcomparator.EvenOddComparator;

public class Main {
    public static void main(String[] args) {
        int[] arr = { 3, 1, 5, 8, 4, 2, 7, 6 };

        ArraySorter.sort(arr, new EvenOddComparator());

        for (int num : arr) {
            System.out.print(num + " ");
        }
        System.out.println();
    }
}
```

